"""Build the offline annual-report dashboard from the three approved markdown inputs.

Only owned outputs dashboard.html and evidence/stage4-validation.json are written.
No remote calls, packages, original filings, or earlier-stage scripts are used.
"""
from pathlib import Path
import ast
import hashlib
import html
import json
import math
import re
import shutil
import subprocess

ROOT = Path(__file__).resolve().parents[1]
NAMES = ('financials.md', 'trends.md', 'exec-summary.md')
TEXT = {n: (ROOT / n).read_text(encoding='utf-8-sig') for n in NAMES}

def ledger(name):
    return json.loads(re.search(r'```json\s*([\s\S]*?)```', TEXT[name]).group(1))

financials, trends = ledger('financials.md'), ledger('trends.md')
assert len(financials) == 385 and len(trends) == 99
sources = {}
for name in ('financials.md', 'trends.md'):
    for line in TEXT[name].splitlines():
        match = re.match(r'^\|\s*([A-Z][A-Z0-9_]*)\s*\|\s*([^|]+)\|\s*\[([^]]+)\]\((https://[^)]+)\)\s*\|', line)
        if match:
            ident, locator, title, url = match.groups()
            sources.setdefault(ident, dict(id=ident, locator=locator.strip(), title=title, url=url))
assert len(sources) >= 40
for row in financials + trends:
    assert all(s.strip() in sources for s in row['source'].split(';')), row

def inline(s):
    s = html.escape(s)
    s = re.sub(r'\[([^]]+)\]\((https://[^)]+)\)', r'<a href="\2" target="_blank" rel="noopener noreferrer">\1</a>', s)
    return re.sub(r'\*\*([^*]+)\*\*', r'<strong>\1</strong>', s)

summary = {}
for title in ('5 headlines', '3 risks', '3 questions'):
    part = re.search(r'## ' + re.escape(title) + r'\s*([\s\S]*?)(?=\n## |\Z)', TEXT['exec-summary.md']).group(1)
    summary[title] = [inline(x.strip()) for x in re.split(r'\n\s*\d+\. ', '\n' + part) if x.strip()]
assert [len(summary[t]) for t in summary] == [5, 3, 3]

F = {x['id']: x for x in financials}
T = {x['id']: x for x in trends}
checks = []
def check(name, actual, expected, tolerance=1e-7):
    assert math.isclose(actual, expected, abs_tol=tolerance, rel_tol=0), (name, actual, expected)
    checks.append(dict(check=name, actual=actual, expected=expected, passed=True))

def value(i): return F[i]['value']
for y in ('fy25', 'fy26'):
    check('segment revenue ' + y, value('cn_revenue_' + y) + value('graphics_revenue_' + y), value('revenue_' + y))
    check('segment operating income ' + y, value('cn_oi_' + y) + value('graphics_oi_' + y), value('segment_oi_' + y))
    check('unallocated bridge ' + y, value('segment_oi_' + y) + value('sbc_bridge_' + y) + value('unallocated_opex_' + y) + value('acquisition_bridge_' + y), value('operating_income_' + y))
    check('Data Center components ' + y, value('dc_compute_' + y) + value('dc_networking_' + y), value('dc_revenue_' + y))
    check('end-market total excluding nested subcategories ' + y, sum(value(x + '_' + y) for x in ['dc_revenue', 'gaming', 'proviz', 'automotive', 'oem_other']), value('revenue_' + y))
    check('cash and marketable securities ' + y, value('cash_equivalents_' + y) + value('marketable_securities_' + y), value('cash_marketable_' + y))
    check('company-defined free cash flow ' + y, value('cfo_' + y) - value('capex_purchases_' + y) - value('capex_principal_' + y), value('fcf_' + y))
    check('headquarters-based geography ' + y, sum(value('geo_' + x + '_' + y) for x in ['us', 'taiwan', 'china', 'other']), value('revenue_' + y))
check('four quarters reconcile to FY2026 revenue', sum(value('revenue_q' + str(q) + 'fy26') for q in range(1, 5)), value('revenue_fy26'))

def numeric_expression(s):
    # Only a numeric arithmetic AST is evaluated; neither input prose nor code runs.
    s = s.replace(',', '').replace('−', '-').replace('×', '*').replace('÷', '/')
    tree = ast.parse(s, mode='eval')
    allowed = (ast.Expression, ast.Constant, ast.BinOp, ast.UnaryOp, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Pow, ast.USub, ast.UAdd, ast.Load)
    assert all(isinstance(n, allowed) for n in ast.walk(tree)), s
    return eval(compile(tree, '<numeric arithmetic>', 'eval'), {'__builtins__': {}})

for row in trends:
    expr = row['formula']['numerical_expression']
    check('trend arithmetic: ' + row['id'], numeric_expression(expr), row['value'], 1e-7)

